"""Export output must match the files generated by the original API (see tests/golden)."""

from __future__ import annotations

import copy
import warnings
from pathlib import Path

import pytest

from gearbox.export import Dimension, ExportGear, ExportPair, ExportTarget, export_gear, export_pair
from tests.scenarios import scenario

GOLDEN = Path(__file__).parent / "golden" / "export"
SCENARIOS = sorted(p.name for p in GOLDEN.iterdir() if p.is_dir())
TARGETS = ("comsol", "abaqus", "ansys")
DIMENSIONS = ("2D", "3D")


def _run(kind: str, transmission, target: str, dimension: str, out: Path) -> Path:
    model = f"{kind}_{dimension.lower()}_{target}"
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        if kind == "pair":
            return export_pair(transmission, target, out, model, dimension)
        gear = transmission.pinion if kind == "pinion" else transmission.wheel
        return export_gear(gear, target, out, model, dimension)


@pytest.mark.parametrize("dimension", DIMENSIONS)
@pytest.mark.parametrize("target", TARGETS)
@pytest.mark.parametrize("kind", ["pinion", "wheel", "pair"])
@pytest.mark.parametrize("name", SCENARIOS)
def test_export_matches_golden(name, kind, target, dimension, tmp_path):
    out = tmp_path / "out"  # created by the exporter
    written = _run(kind, scenario(name), target, dimension, out)

    expected = (GOLDEN / name / written.name).read_text()
    assert written.read_text().replace(str(out), "<OUTPUT_DIR>") == expected


def test_scenarios_have_golden_files():
    assert SCENARIOS == ["helical15_sr20", "spur_sr0"]
    assert len(list((GOLDEN / "spur_sr0").iterdir())) == 18


@pytest.mark.parametrize("target", TARGETS)
def test_export_does_not_mutate_input(target, tmp_path):
    transmission = scenario("helical15_sr20")
    before = copy.deepcopy(transmission)

    for dimension in DIMENSIONS:
        _run("pinion", transmission, target, dimension, tmp_path)
        _run("pair", transmission, target, dimension, tmp_path)

    assert transmission.pinion == before.pinion
    assert transmission.wheel == before.wheel
    assert vars(transmission.pinion) == vars(before.pinion)


def test_repeated_export_is_identical(tmp_path):
    transmission = scenario("spur_sr0")
    first = _run("pair", transmission, "ansys", "2D", tmp_path / "a").read_text()
    second = _run("pair", transmission, "ansys", "2D", tmp_path / "b").read_text()
    assert first.replace(str(tmp_path / "a"), "") == second.replace(str(tmp_path / "b"), "")


def test_accepts_enums_aliases_and_gear_sequence(tmp_path):
    transmission = scenario("spur_sr0")
    gears = (transmission.pinion, transmission.wheel)
    a = export_pair(gears, ExportTarget.COMSOL, tmp_path, "a", Dimension.TWO_D)
    b = export_pair(transmission, "matlab_comsol", tmp_path, "a b", "2d")
    assert a.suffix == ".m"
    assert b.name == "a_b.m"
    assert ExportGear(transmission.pinion).export("abaqus", tmp_path, "g", 3).suffix == ".py"
    assert ExportPair(transmission).export("ANSYS", tmp_path, "p").suffix == ".js"


def test_invalid_options_raise_value_error(tmp_path):
    transmission = scenario("spur_sr0")
    with pytest.raises(ValueError, match="target"):
        export_gear(transmission.pinion, "nastran", tmp_path)
    with pytest.raises(ValueError, match="dimension"):
        export_gear(transmission.pinion, "comsol", tmp_path, dimension="4D")
    with pytest.raises(ValueError, match="dimension"):
        export_pair(transmission, "comsol", tmp_path, dimension="x")


@pytest.mark.parametrize("role", ["pinion", "wheel"])
def test_exported_tooth_has_the_modelled_root_and_tip_diameters(role):
    """The profile engine takes the fillet radius and clearance in mm, not as tool coefficients."""
    from gearbox.export.exporters import _build_wheel

    gear = getattr(scenario("spur_sr0"), role)
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        data = _build_wheel(gear).data
    assert data["d_f"] == pytest.approx(gear.root_diameter, rel=1e-9)
    assert data["d_a"] == pytest.approx(gear.tip_diameter, rel=1e-9)
    assert data["rho_f"] == pytest.approx(gear.root_fillet_radius, rel=1e-12)
